From 586e524a5ae5f853e265dca2fe08ebed5a89c0d5 Mon Sep 17 00:00:00 2001
From: neomanu <neuvine@gmail.com>
Date: Mon, 18 Aug 2014 17:24:37 +0530
Subject: [PATCH] Fix errors introduced due to "printk: rename printk_sched to
 printk_deferred"

d07ef0f6df9f9e48406eea3aad33aca646e818e7 "printk: rename printk_sched to printk_deferred" brought along errors.
This patch fixes that.

diff --git a/mediatek/kernel/drivers/wdk/wd_kicker.c b/mediatek/kernel/drivers/wdk/wd_kicker.c
index 376b3971..5b19f690 100644
--- a/mediatek/kernel/drivers/wdk/wd_kicker.c
+++ b/mediatek/kernel/drivers/wdk/wd_kicker.c
@@ -309,17 +309,17 @@ static int kwdt_thread(void *arg)
 			   //only process WDT info if thread-x is on cpu-x
 			   spin_lock(&lock);
 			   local_bit = kick_bit;
-			   printk_sched("[WDK], local_bit:0x%x, cpu:%d,RT[%lld]\n", local_bit, cpu,sched_clock());
+			   printk_deferred("[WDK], local_bit:0x%x, cpu:%d,RT[%lld]\n", local_bit, cpu,sched_clock());
 			   if((local_bit&(1<<cpu)) == 0)
 			   {
 				//printk("[WDK]: set  WDT kick_bit\n");
 				local_bit |= (1<<cpu);
 				//aee_rr_rec_wdk_kick_jiffies(jiffies);
 			   }
-			   printk_sched("[WDK], local_bit:0x%x, cpu:%d, check bit0x:%x,RT[%lld]\n", local_bit, cpu, wk_check_kick_bit(),sched_clock());
+			   printk_deferred("[WDK], local_bit:0x%x, cpu:%d, check bit0x:%x,RT[%lld]\n", local_bit, cpu, wk_check_kick_bit(),sched_clock());
 			   if(local_bit == wk_check_kick_bit())
 			   {
-			      printk_sched("[WDK]: kick Ex WDT,RT[%lld]\n",sched_clock());
+			      printk_deferred("[WDK]: kick Ex WDT,RT[%lld]\n",sched_clock());
 			      loc_wk_wdt->kick_wdt(WK_WDT_EXT_TYPE);// for KICK external wdt
 			      local_bit = 0;
 			   }
@@ -327,7 +327,7 @@ static int kwdt_thread(void *arg)
 			   spin_unlock(&lock);

                		   #ifdef CONFIG_LOCAL_WDT
-			   printk_sched("[WDK]: cpu:%d, kick local wdt,RT[%lld]\n", cpu,sched_clock());
+			   printk_deferred("[WDK]: cpu:%d, kick local wdt,RT[%lld]\n", cpu,sched_clock());
 			   // kick local wdt
 			   loc_wk_wdt->kick_wdt(WK_WDT_LOC_TYPE); 
 			   #endif
@@ -353,7 +353,7 @@ static int kwdt_thread(void *arg)
 		   rtc_time_to_tm(tv.tv_sec, &tm);
 		   tv_android.tv_sec -= sys_tz.tz_minuteswest*60;
 		   rtc_time_to_tm(tv_android.tv_sec, &tm_android);
-		   printk_sched("[thread:%d][RT:%lld] %d-%02d-%02d %02d:%02d:%02d.%u UTC; android time %d-%02d-%02d %02d:%02d:%02d.%03d\n",  current->pid,sched_clock(),
+		   printk_deferred("[thread:%d][RT:%lld] %d-%02d-%02d %02d:%02d:%02d.%u UTC; android time %d-%02d-%02d %02d:%02d:%02d.%03d\n",  current->pid,sched_clock(),
 		   tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
 		   tm.tm_hour, tm.tm_min, tm.tm_sec,
 		   (unsigned int) tv.tv_usec,
-- 
